function NativeAdmission {
    $os = Get-CimInstance Win32_OperatingSystem
    $used = 100 * (1 - $os.FreePhysicalMemory / $os.TotalVisibleMemorySize)
    $freeGiB = $os.FreePhysicalMemory / 1MB
    if ($used -ge 70 -or $freeGiB -lt 10) { throw "Native admission requires RAM <70% and >=10 GiB free: used=$used freeGiB=$freeGiB" }
}

function Resources {
    $os = Get-CimInstance Win32_OperatingSystem
    $used = 100 * (1 - $os.FreePhysicalMemory / $os.TotalVisibleMemorySize)
    if ($used -ge 80) { throw "RAM guard: $used" }
    $jobs = @(Get-CimInstance Win32_Process | Where-Object { $_.Name -match '^(cmake|MSBuild|cl|link|ctest|AzTestRunner|Editor|AssetProcessor|AssetProcessorBatch|AssetBuilder|JEEditorFixture\.GameLauncher|AssetBundler|AssetBundlerBatch|MaterialEditor|MaterialCanvas|PassCanvas|ShaderManagementConsole|JENativeSdkConsumer)\.exe$' })
    if ($jobs.Count) { throw 'Another native phase is active; preserve its ownership.' }
}

function Run($phase, $exe, $arguments, $cwd, $pathValue = $null, $timeoutMs = 1800000) {
    Resources
    NativeAdmission
    $info = [Diagnostics.ProcessStartInfo]::new(); $info.FileName = $exe; $info.WorkingDirectory = $cwd
    $info.UseShellExecute = $false; $info.CreateNoWindow = $true; $info.RedirectStandardOutput = $true; $info.RedirectStandardError = $true
    $info.Environment['MSBUILDDISABLENODEREUSE'] = '1'
    if ($pathValue) { $info.Environment['PATH'] = $pathValue }
    foreach ($arg in $arguments) { $info.ArgumentList.Add([string]$arg) }
    $process = [Diagnostics.Process]::new(); $process.StartInfo = $info
    $clock = [Diagnostics.Stopwatch]::StartNew()
    if (!$process.Start()) { throw "Cannot start $phase" }
    $ownedPid = $process.Id; $creation = $process.StartTime.ToUniversalTime()
    Save "$phase.start.json" @{pid=$ownedPid;creationUtc=$creation.ToString('o');executable=$exe;argv=@($arguments);cwd=$cwd;path=$pathValue}
    $stdout = $process.StandardOutput.ReadToEndAsync(); $stderr = $process.StandardError.ReadToEndAsync()
    $priorityError = $null
    try { $process.PriorityClass = [Diagnostics.ProcessPriorityClass]::BelowNormal } catch { $priorityError = $_.Exception.Message }
    $guard = $false; $timedOut = $false
    while (!$process.WaitForExit(3000)) {
        $os = Get-CimInstance Win32_OperatingSystem
        $guard = (100 * (1 - $os.FreePhysicalMemory / $os.TotalVisibleMemorySize)) -ge 80
        $timedOut = $clock.ElapsedMilliseconds -ge $timeoutMs
        if ($guard -or $timedOut -or $priorityError) {
            $identity = Get-CimInstance Win32_Process -Filter "ProcessId=$ownedPid"
            if ($identity -and ([IO.Path]::GetFullPath($identity.ExecutablePath) -ine [IO.Path]::GetFullPath($exe) -or [Math]::Abs((([DateTime]$identity.CreationDate).ToUniversalTime() - $creation).TotalMilliseconds) -ge 1000)) { throw 'PID identity changed; cannot terminate safely.' }
            if (!$process.HasExited) { $process.Kill($true) }; break
        }
    }
    $process.WaitForExit(); $code = $process.ExitCode; $clock.Stop()
    [IO.File]::WriteAllText("$out/$phase.stdout.log", $stdout.GetAwaiter().GetResult())
    [IO.File]::WriteAllText("$out/$phase.stderr.log", $stderr.GetAwaiter().GetResult())
    Save "$phase.result.json" @{exitCode=$code;seconds=$clock.Elapsed.TotalSeconds;ramGuardTriggered=$guard;timedOut=$timedOut;priorityRequested='BelowNormal';priorityError=$priorityError;stdout=(Pin "$out/$phase.stdout.log");stderr=(Pin "$out/$phase.stderr.log")}
    $process.Dispose()
    if ($code -ne 0 -or $guard -or $timedOut -or $priorityError) { throw "Native phase failed: $phase, exit=$code, RAM=$guard, timeout=$timedOut" }
}

function NoReparse($path) {
    $current = [IO.Path]::GetFullPath($path)
    while ($current) {
        if ((Test-Path -LiteralPath $current) -and ((Get-Item -LiteralPath $current -Force).Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw "Reparse point: $current" }
        $next = [IO.Path]::GetDirectoryName($current)
        if ($next -eq $current) { break }; $current = $next
    }
}

function CopyPinned($pin, $destination) {
    NoReparse $destination
    if (Test-Path -LiteralPath $destination) { throw "No overwrite: $destination" }
    [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($destination)) | Out-Null
    [IO.File]::Copy($pin.path,$destination,$false)
    Verify @([pscustomobject]@{path=$destination;bytes=$pin.bytes;sha256=$pin.sha256})
}

function CheckNoEngineFallback($text) {
    $normal = $text.Replace('\','/').ToLowerInvariant()
    foreach ($part in @('Engine','Editor','Code','Gems','Assets','Registry')) {
        if ($normal.Contains(($repo+'/'+$part+'/').ToLowerInvariant())) { throw "Source-engine path in external consumer: $part" }
    }
    foreach ($part in @('bin','lib','Engine','Editor','Code','Gems')) {
        if ($normal.Contains(($producer+'/'+$part+'/').ToLowerInvariant())) { throw "Original-engine output/include fallback: $part" }
    }
}

function VerifyOverlay {
    $dlls = @(Get-ChildItem -LiteralPath "$overlay/bin" -Filter '*.dll' -File)
    if ($dlls.Count -ne 32 -or (($dlls.Name | Sort-Object) -join '|') -cne (($recipe.expectedRuntimeNames | Sort-Object) -join '|')) { throw 'Overlay runtime closure changed.' }
    foreach ($dll in $dlls) {
        NoReparse $dll.FullName
        $expected = if ($providerMap.ContainsKey($dll.Name)) { $providerMap[$dll.Name] } else { @($runtime | Where-Object { $_.name -ceq $dll.Name })[0] }
        Verify @([pscustomobject]@{path=$dll.FullName;bytes=$expected.bytes;sha256=$expected.sha256})
    }
    foreach ($name in @('RenderIntegration.lib','EditorRenderIntegration.lib')) { $expected=$providerMap[$name]; Verify @([pscustomobject]@{path="$overlay/lib/$name";bytes=$expected.bytes;sha256=$expected.sha256}) }
    foreach ($pin in $recipe.headerPins) { Verify @([pscustomobject]@{path="$overlay/include/$($pin.relative)";bytes=$pin.bytes;sha256=$pin.sha256}) }
}
